SELECT id, product_name, brand, tags, supplier_id, COUNT(stock_qty) OVER (PARTITION BY MONTH(launch_date), brand) AS launch_date_month_count_stock_qty, AVG(price) OVER (PARTITION BY brand, category ORDER BY cost, id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING) AS price_avg_5_prior, AVG(cost) OVER (PARTITION BY category, supplier_id ORDER BY stock_qty, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS cost_avg_6 FROM products WHERE category = 'Electronics';
